insert into public.news_impacts (campaign_id, title, url, published_on, scope, stance, reading, moves, sources, written_by) values ('ca000000-0000-4000-8000-000000000001', 'Ruto hands over 2,157 affordable homes at Pioneer, Eldoret, on a 10-day Rift tour', 'https://nation.africa/kenya/news/politics/ruto-takes-re-election-pitch-to-eldoret-home-turf-defends-uda-odm-pact-5636008', '2026-10-18', 'national', 'opening', 'On 18 October Ruto commissioned the Sh5.3bn Pioneer estate in Eldoret and handed keys to 2,157 owners (552 social, 1,065 affordable, 540 market units; local Jua Kali groups made the doors and windows), and promised 12,429 more homes in Uasin Gishu. It was the centrepiece of a 10-day North Rift tour where he campaigned openly for a second term beside ODM leaders and launched the slogan ''Usawa ni Sawa''. Online, the pictures travelled; so did the question ''who can afford it?''
